import React, {useMemo} from 'react';




function DeploymentCard(props) {
const random = useMemo(() => Math.random(), []);
  return (
    <>
        
       <div className="card" style={{width: "25%", margin: "auto", marginTop: "20px"}}>
            <img src={props.image} className="card-img-top" alt="Loading..."  />
            <div class="card-body">
                <h5 class="card-title">{props.title}</h5>
                <p class="card-text">{props.description}</p>
                <div className="container">
                <div className="row">
                
                <br />
                <p class="d-inline-flex gap-1" style={{display: "flex", flexDirection: "row", alignItems: "center", justifyContent: "center", width: "100%"}}>
                    <a download={props.title} href={props.image} className="btn btn-outline-primary" role="button" style={{width: "100%"}} >Download Image</a>
                    <a class="btn btn-outline-secondary" data-bs-toggle="collapse" href={"#" + random} role="button" aria-expanded="false" aria-controls={random} >
                        Attendees
                    </a>
                </p>
                <div className="collapse" id={random}>
                
                    <ul className="list-group">
                        {props.attendees.map((attendee, index) => (
                            <li className="list-group-item" key={index}>
                                {attendee}
                            </li>
                        ))}
                    </ul>
                    
                </div>
                <hr class="my-4" />
                    {props.medals.map((medal, index) => (
                    <div className="col-4 col-sm-4 col-md-4 col-lg-4 mb-2 d-flex justify-content-center" key={index}>
                        <img
                        src={medal}
                        alt={`Medal ${index}`}
                        className="img-fluid rounded"
                        style={{
                            width: "100%",
                            height: "auto", 
                            objectFit: "fill",
                            margin: "0 auto",
                            border: "2px solid silver",
                        }}
                        />
                    </div>
                    ))}

                    {props.campaignMedals.map((medal, index) => (
                    <div className="col-4 col-sm-4 col-md-4 col-lg-4 mb-2 d-flex justify-content-center" key={index}>
                        <img
                        src={medal}
                        alt={`Medal ${index}`}
                        className="img-fluid rounded"
                        style={{
                            width: "100%",
                            height: "auto", 
                            objectFit: "fill",
                            margin: "0 auto",
                            border: "2px solid gold",
                            
                            
                        }}
                        />
                    </div>
                    ))}
                </div>
                </div>
                
            </div>
        </div>
                
    </>
  );
}

export default  DeploymentCard;